                      onClick={() => setSidebarOpen(false)}
                      style={{ animationDelay: `${index * 50}ms` }}
                    >
                      <item.icon className="h-5 w-5 mr-3 group-hover:scale-110 transition-transform" />
                      {item.name}
                    </Link>
